V43_GROUP_META = {
    "autonomic": ("🫀", "Autonomic & Cardiovascular"),
    "exercise": ("🔥", "Exercise · Heat · Respiratory"),
    "capacity": ("📈", "Capacity & Training Load"),
}


def _v43_clean_numeric(values):
    out = []
    for value in values or []:
        try:
            value = float(value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            out.append(value)
    return out


def _v43_middle_range(values, min_samples=5):
    vals = sorted(_v43_clean_numeric(values))
    if len(vals) < min_samples:
        return None
    lo = percentile(vals, 0.25)
    hi = percentile(vals, 0.75)
    med = statistics.median(vals)
    return {"low": lo, "high": hi, "median": med, "n": len(vals)}


def _v43_fmt(value, decimals=1):
    if value is None:
        return "—"
    if decimals <= 0:
        return f"{value:.0f}"
    return f"{value:.{decimals}f}"


def _v43_dynamic_reference(values, current=None, unit="", decimals=1, min_samples=5, label="YOUR DYNAMIC BASELINE"):
    rng = _v43_middle_range(values, min_samples=min_samples)
    if not rng:
        return None
    suffix = f" {unit}" if unit else ""
    value = f"{_v43_fmt(rng['low'], decimals)}–{_v43_fmt(rng['high'], decimals)}{suffix} · middle 50% of {rng['n']} observations"
    assessment = None
    try:
        current = float(current)
        if current < rng["low"]:
            assessment = "BELOW YOUR HABITUAL RANGE"
        elif current > rng["high"]:
            assessment = "ABOVE YOUR HABITUAL RANGE"
        else:
            assessment = "WITHIN YOUR HABITUAL RANGE"
    except (TypeError, ValueError):
        pass
    return {"label": label, "value": value, "assessment": assessment}


def _v43_rolling_geomeans(series, today, horizon_days=42, window_days=7, min_samples=3):
    """Rolling geometric means aligned with the 7-day HRV-stability concept."""
    rows = [(d, float(v)) for d, v, *_ in (series or []) if isinstance(v, (int, float)) and v > 0]
    anchors = sorted({d for d, _ in rows if today - timedelta(days=horizon_days - 1) <= d <= today})
    out = []
    for anchor in anchors:
        vals = [v for d, v in rows if anchor - timedelta(days=window_days - 1) <= d <= anchor]
        if len(vals) >= min_samples:
            out.append((anchor, math.exp(statistics.mean(math.log(v) for v in vals))))
    return out


def _v43_load_ratio_history(season_activities, today, weeks=8):
    """Historical 7d/prior-3w ratios using the exact window definition of Training State."""
    def load_between(start_day, end_day):
        total = 0.0
        for activity in season_activities or []:
            day = _v40_activity_day(activity)
            if day is None or not (start_day <= day <= end_day):
                continue
            load = activity.get("icu_training_load")
            if isinstance(load, (int, float)) and not isinstance(load, bool):
                total += max(0.0, float(load))
        return total

    out = []
    for i in range(weeks + 1):
        anchor = today - timedelta(days=7 * i)
        load7 = load_between(anchor - timedelta(days=6), anchor)
        prior21 = load_between(anchor - timedelta(days=27), anchor - timedelta(days=7))
        prior_weekly = prior21 / 3.0 if prior21 > 0 else None
        if prior_weekly and prior_weekly > 0:
            out.append((anchor, load7 / prior_weekly))
    out.sort(key=lambda x: x[0])
    return out


def _v43_reference_profile(cards, context):
    """Attach a readable personal comparator and a cautious research anchor to every metric."""
    cards = cards or []
    context = context or {}

    # Pre-compute dynamic, like-for-like personal comparators where the data allow it.
    hrv_roll = _v43_rolling_geomeans(context.get("hrv_series"), context.get("today"), horizon_days=42)
    hrv_ref = _v43_dynamic_reference([v for _, v in hrv_roll[:-1]], context.get("hrv_current"), "ms", 0, 5)

    si_ref = _v43_dynamic_reference(context.get("si_values"), context.get("si_current"), "", 0, 5)
    poincare_ref = _v43_dynamic_reference(context.get("poincare_values"), context.get("poincare_current"), "ratio", 2, 5)
    rpp_ref = _v43_dynamic_reference(context.get("rpp_values"), context.get("rpp_current"), "bpm·mmHg", 0, 3)
    resp_ref = _v43_dynamic_reference(context.get("resp_values"), context.get("resp_current"), "brpm", 1, 7)
    mets_ref = _v43_dynamic_reference(context.get("mets_values"), context.get("mets_current"), "MET", 1, 4)
    load_ref = _v43_dynamic_reference(context.get("load_ratio_values"), context.get("load_ratio_current"), "×", 2, 4)
    mono_ref = _v43_dynamic_reference(context.get("monotony_values"), context.get("monotony_current"), "", 2, 2)

    ref_by_key = {
        "hrv_stability": hrv_ref,
        "baevsky_si": si_ref,
        "poincare": poincare_ref,
        "rpp": rpp_ref,
        "respiration": resp_ref,
        "functional_capacity": mets_ref,
        "load_context": load_ref,
        "training_monotony": mono_ref,
    }

    if context.get("hard_max_hr"):
        vals = _v43_clean_numeric(context.get("hard_max_hr"))
        if vals:
            ref_by_key["chronotropic_response"] = {
                "label": "YOUR OBSERVED HARD-EFFORT CONTEXT",
                "value": f"median peak {statistics.median(vals):.0f} bpm · observed max {max(vals):.0f} bpm · {len(vals)} efforts",
                "assessment": None,
            }

    if isinstance(context.get("aero_baseline_decoupling"), (int, float)):
        change = context.get("aero_decoupling_change")
        assessment = None
        if isinstance(change, (int, float)):
            assessment = "LOWER DRIFT THAN PRIOR BASELINE" if change < -0.5 else ("HIGHER DRIFT THAN PRIOR BASELINE" if change > 0.5 else "SIMILAR TO PRIOR BASELINE")
        ref_by_key["aerobic_decoupling"] = {
            "label": "YOUR COMPARABLE Z2 BASELINE",
            "value": f"{context.get('aero_baseline_decoupling'):.1f}% prior non-HEAT decoupling",
            "assessment": assessment,
        }

    # Multisignal strain is rule-based rather than a single continuous measure.
    ref_by_key["multisignal_strain"] = {
        "label": "THE LAB PERSONAL RULE",
        "value": "0 aligned warnings = CLEAR · 1 = MIXED · ≥2 = WATCH; each component is judged against its own personal baseline first.",
        "assessment": None,
    }

    for card in cards:
        group_icon, group_label = V43_GROUP_META.get(card.get("group"), ("🔬", "Advanced Physiology"))
        card["group_icon"] = group_icon
        card["group_label"] = group_label
        card["reference"] = {
            "personal": ref_by_key.get(card.get("key")),
            "research": V43_RESEARCH_REFERENCES.get(card.get("key"), "No universal cut-off is used; THE LAB prioritizes protocol quality and your longitudinal baseline."),
        }
    return cards


def _v43_metric_display(cards):
    """Priority order: attention → live → learning → collapsed gaps."""
    cards = cards or []
    attention_states = {"WATCH", "ELEVATED"}
    live_states = {"TRACKING", "CONTROLLED", "CLEAR", "MIXED"}
    gap_states = {"DATA NEEDED", "UNAVAILABLE"}

    attention = [c for c in cards if c.get("status") in attention_states]
    active = [c for c in cards if c.get("status") in live_states]
    learning = [c for c in cards if c.get("status") == "LEARNING"]
    gaps = [c for c in cards if c.get("status") in gap_states]
    other = [c for c in cards if c not in attention and c not in active and c not in learning and c not in gaps]
    active.extend(other)

    key_order = {"WATCH": 0, "ELEVATED": 1, "TRACKING": 0, "CONTROLLED": 1, "CLEAR": 2, "MIXED": 3, "LEARNING": 0, "DATA NEEDED": 0, "UNAVAILABLE": 1}
    sorter = lambda c: (key_order.get(c.get("status"), 9), str(c.get("label") or ""))
    attention.sort(key=sorter)
    active.sort(key=sorter)
    learning.sort(key=sorter)
    gaps.sort(key=sorter)

    sections = []
    if attention:
        sections.append({"key": "attention", "icon": "⚠️", "title": "Needs attention", "subtitle": "Live metrics currently outside or near the edge of their intended context. Read them with the personal reference shown on each card.", "cards": attention})
    if active:
        sections.append({"key": "active", "icon": "✅", "title": "Active now", "subtitle": "Metrics with enough usable data to provide current longitudinal context.", "cards": active})
    if learning:
        sections.append({"key": "learning", "icon": "🧠", "title": "THE LAB is learning", "subtitle": "Usable ingredients exist, but more comparable observations are required before these signals earn stronger authority.", "cards": learning})
    return sections, gaps


def build_advanced_physiology_metrics(season_activities, season_wellness, metrics, training_state, vo2_trend, feeling_trend=None, planning_context=None, now=None):
    """Evidence-led physiology metrics with explicit data sufficiency and personal learning.

    Science proposes useful questions; deterministic Python decides whether the
    available athlete data can answer them. Clinical cut-offs from patient or
    laboratory populations are never converted directly into athlete diagnoses.
    Personal baselines, repeatability and protocol quality take priority.
    """
    now = now or get_rome_now()
    today = now.date()
    season_activities = season_activities or []
    season_wellness = season_wellness or []
    metrics = metrics or {}
    training_state = training_state or {}
    vo2_trend = vo2_trend or {}
    planning_context = planning_context or {}

    cutoff_42 = today - timedelta(days=41)
    recent42 = []
    for a in season_activities:
        d = _v40_activity_day(a)
        if d and cutoff_42 <= d <= today:
            recent42.append(a)

    hard42 = [a for a in recent42 if _v40_is_hard_candidate(a)]
    hard_max_hr = []
    hrr_candidates = []
    dfa_candidates = []
    psi_candidates = []
    skin_only_heat = []
    resting_rr_hint = []
    for a in recent42:
        streams = _v40_stream_names(a)
        if any(x in streams for x in ("hrv", "rr", "rr_intervals", "rri")):
            resting_rr_hint.append(a)
        is_hard = a in hard42
        if is_hard:
            try:
                mx = float(a.get("max_heartrate"))
                if 80 <= mx <= 230:
                    hard_max_hr.append(mx)
            except (TypeError, ValueError):
                pass
            has_hr = any(x in streams for x in ("heartrate", "heart_rate", "hr", "fixed_heartrate")) or any("heart" in x for x in streams)
            if has_hr and isinstance(a.get("max_heartrate"), (int, float)):
                hrr_candidates.append(a)
            if any(("dfa_a1" in x) or ("alpha1" in x) or ("alpha_1" in x) or ("alphahrv" in x) for x in streams):
                dfa_candidates.append(a)
        if _is_heat_name(a.get("name")):
            has_core = any(x == "core_temperature" or "core_temperature" in x for x in streams)
            has_skin_or_ambient = any(x in ("skin_temperature", "temp", "temperature") or "skin_temperature" in x for x in streams)
            has_hr_stream = any(x in streams for x in ("heartrate", "heart_rate", "hr", "fixed_heartrate")) or any("heart" in x for x in streams)
            if has_core and has_hr_stream:
                psi_candidates.append(a)
            elif has_skin_or_ambient:
                skin_only_heat.append(a)

    cards = []

    # ------------------------------------------------------------------
    # AUTONOMIC & CARDIOVASCULAR
    # ------------------------------------------------------------------

    # Research addition: weekly-averaged LnRMSSD + day-to-day stability.
    hrv_series = _v41_wellness_series(season_wellness, "hrv", 5, 350)
    hrv7 = _v41_recent_values(hrv_series, today, 7)
    hrv_prior = [x for x in hrv_series if today - timedelta(days=34) <= x[0] <= today - timedelta(days=7)]
    if len(hrv7) >= 3:
        recent_logs = [math.log(x[1]) for x in hrv7]
        gm7 = math.exp(statistics.mean(recent_logs))
        cv_ln = (statistics.pstdev(recent_logs) / abs(statistics.mean(recent_logs)) * 100.0) if len(recent_logs) >= 2 and statistics.mean(recent_logs) else 0.0
        prior_gm = math.exp(statistics.mean(math.log(x[1]) for x in hrv_prior)) if hrv_prior else None
        delta = ((gm7 / prior_gm) - 1.0) * 100.0 if prior_gm else None
        status = "TRACKING" if len(hrv7) >= 4 and len(hrv_prior) >= 8 else "LEARNING"
        cls = "cyan" if status == "TRACKING" else "purple"
        secondary = f"{len(hrv7)} readings / 7d · LnRMSSD CV {cv_ln:.1f}%"
        if delta is not None:
            secondary += f" · {delta:+.1f}% vs prior"
        cards.append(_v40_card(
            "hrv_stability", "〰️", "HRV STABILITY · 7d LnRMSSD", status, cls,
            f"{gm7:.0f} ms geometric mean", secondary,
            "Looks at the weekly level and day-to-day stability of rMSSD rather than reacting to one morning. In endurance athletes, averaged trends are generally more informative than an isolated HRV reading, and both unusually high and unusually low HRV can require context.",
            "THE LAB will learn your normal 7-day level and normal variability, then interpret departures together with resting HR, sleep, training and subjective recovery.",
            group="autonomic", evidence="Plews et al. · 2012–2013"
        ))
    else:
        cards.append(_v40_card(
            "hrv_stability", "〰️", "HRV STABILITY · 7d LnRMSSD", "LEARNING" if hrv_series else "UNAVAILABLE", "purple" if hrv_series else "grey",
            "—", f"{len(hrv7)} usable HRV reading{'s' if len(hrv7) != 1 else ''} in the last 7 days",
            "Weekly averaged rMSSD helps distinguish a real autonomic trend from normal morning-to-morning noise. THE LAB will not call a trend from sparse samples.",
            "Aim for repeated comparable morning HRV measurements; four or more readings in a week plus prior history make this signal substantially more useful.",
            group="autonomic", evidence="Plews et al. · 2012–2013"
        ))

    # User-proposed metric: Baevsky SI, using Intervals' native wellness field when present.
    si_series = _v41_wellness_series(season_wellness, "baevskySI", 0.01, 5000)
    si_recent = _v41_recent_values(si_series, today, 28)
    if si_series and (today - si_series[-1][0]).days <= 7:
        current_si = si_series[-1][1]
        baseline_vals = [x[1] for x in si_recent[:-1]]
        baseline_med = statistics.median(baseline_vals) if baseline_vals else None
        status = "TRACKING" if len(si_recent) >= 5 else "LEARNING"
        secondary = f"{len(si_recent)} readings / 28d"
        if baseline_med:
            secondary += f" · personal median {baseline_med:.0f} · {((current_si / baseline_med)-1)*100:+.0f}%"
        cards.append(_v40_card(
            "baevsky_si", "🧠", "BAEVSKY STRESS INDEX · SI", status, "cyan" if status == "TRACKING" else "purple",
            f"{current_si:.0f}", secondary,
            "Summarises how concentrated the RR-interval distribution becomes; higher values can accompany greater sympathetic/autonomic strain. THE LAB uses the value already exposed by Intervals and compares it with your own repeated resting history instead of turning a generic reference range into a diagnosis.",
            "More standardized resting measurements will establish your personal SI distribution and show whether an elevated day is transient or repeatedly associated with load, sleep, heat or subjective stress.",
            group="autonomic", evidence="Baevsky framework · Huizinga et al. 2025"
        ))
    else:
        cards.append(_v40_card(
            "baevsky_si", "🧠", "BAEVSKY STRESS INDEX · SI", "UNAVAILABLE", "grey",
            "—", "Intervals wellness is not currently supplying baevskySI.",
            "Baevsky SI is derived from the distribution of beat-to-beat RR intervals and is used as an autonomic-strain descriptor. Missing SI is not interpreted as low stress or a normal result.",
            "If Garmin/Intervals begins supplying baevskySI or a standardized RR recording becomes available, THE LAB can move directly into LEARNING and then personal-baseline tracking.",
            group="autonomic", evidence="Baevsky framework · Huizinga et al. 2025"
        ))

    # User-proposed metric: Poincare geometry from same-day rMSSD + SDNN.
    poincare = []
    for row in season_wellness:
        rmssd, sdnn = row.get("hrv"), row.get("hrvSDNN")
        if not isinstance(rmssd, (int, float)) or not isinstance(sdnn, (int, float)) or isinstance(rmssd, bool) or isinstance(sdnn, bool):
            continue
        rmssd, sdnn = float(rmssd), float(sdnn)
        if not (5 <= rmssd <= 350 and 5 <= sdnn <= 400):
            continue
        term = 2.0 * sdnn * sdnn - 0.5 * rmssd * rmssd
        day = _v41_parse_day(row.get("id"))
        if day is None or term <= 0:
            continue
        sd1 = rmssd / math.sqrt(2.0)
        sd2 = math.sqrt(term)
        poincare.append((day, sd1, sd2, sd1 / sd2))
    poincare.sort(key=lambda x: x[0])
    poincare_recent = [x for x in poincare if today - timedelta(days=27) <= x[0] <= today]
    if poincare and (today - poincare[-1][0]).days <= 7:
        day, sd1, sd2, ratio = poincare[-1]
        status = "TRACKING" if len(poincare_recent) >= 5 else "LEARNING"
        cards.append(_v40_card(
            "poincare", "◒", "POINCARÉ GEOMETRY · SD1/SD2", status, "cyan" if status == "TRACKING" else "purple",
            f"{ratio:.2f} ratio", f"SD1 {sd1:.1f} ms · SD2 {sd2:.1f} ms · {len(poincare_recent)} paired days / 28d",
            "Describes the short-axis versus long-axis geometry of beat-to-beat variability. SD1 is mathematically tied to rMSSD and SD2 to rMSSD/SDNN, so THE LAB treats the ratio as a compact geometry view—not as an independent detector of 'sympathetic dominance'.",
            "Repeated same-protocol rMSSD + SDNN days will define your own geometry range and show whether shifts add information beyond the HRV metrics already being tracked.",
            group="autonomic", evidence="Poincaré mathematics · van Roon et al. 2025"
        ))
    else:
        has_rmssd = bool(hrv_series)
        cards.append(_v40_card(
            "poincare", "◒", "POINCARÉ GEOMETRY · SD1/SD2", "DATA NEEDED" if has_rmssd else "UNAVAILABLE", "grey",
            "—", "Same-day rMSSD + SDNN are required.",
            "The SD1/SD2 geometry cannot be reconstructed from rMSSD alone. THE LAB keeps this separate from ordinary HRV rather than manufacturing SDNN or a balance score.",
            "If Intervals begins supplying hrvSDNN alongside your existing HRV, this card will calculate SD1, SD2 and their ratio automatically.",
            group="autonomic", evidence="Poincaré mathematics · van Roon et al. 2025"
        ))

    # User-proposed metric: Deceleration Capacity. We deliberately require the proper signal/protocol.
    dc_status = "DATA NEEDED"
    dc_secondary = "Long, clean resting/sleep RR series required for PRSA"
    if resting_rr_hint:
        dc_secondary += " · exercise HRV stream metadata exists, but is not a validated resting PRSA recording"
    cards.append(_v40_card(
        "deceleration_capacity", "↘️", "DECELERATION CAPACITY · PRSA", dc_status, "grey",
        "—", dc_secondary,
        "PRSA Deceleration Capacity isolates recurring heart-rate slowing patterns and is a vagal/autonomic signal. The classic 4.5 ms prognostic threshold comes from post-myocardial-infarction Holter cohorts, so THE LAB will not apply it to a healthy athlete or to short wellness summaries.",
        "A sufficiently long, artifact-controlled RR series at rest or during sleep plus a validated PRSA implementation is required before this can become a live personal metric.",
        group="autonomic", evidence="Bauer et al. · Lancet 2006"
    ))

    # Existing V40 HR recovery: detect ingredients but do not fake HRR1 from activity summaries.
    if hrr_candidates:
        observed = max(hard_max_hr) if hard_max_hr else None
        cards.append(_v40_card(
            "hrr1", "🫀", "1-MIN HEART-RATE RECOVERY", "LEARNING", "purple",
            f"{len(hrr_candidates)} candidate effort{'s' if len(hrr_candidates) != 1 else ''}",
            (f"HR stream detected · observed peak up to {observed:.0f} bpm" if observed else "HR stream detected"),
            "HRR₁ is the fall in heart rate during the first minute after a hard effort and reflects early autonomic recovery. It is only comparable when the end of effort, recovery posture/activity and the 60-second window are clearly defined.",
            "THE LAB is identifying eligible files. It will learn a personal post-effort baseline rather than apply the clinical ≤12 bpm threshold from a specific exercise-test protocol to arbitrary training intervals.",
            group="autonomic", evidence="Cole et al. 1999 · Daanen et al. 2012"
        ))
    else:
        cards.append(_v40_card(
            "hrr1", "🫀", "1-MIN HEART-RATE RECOVERY", "DATA NEEDED", "grey",
            "—", "No eligible hard effort with a declared HR stream in the current 42-day window.",
            "HRR₁ measures how quickly heart rate falls immediately after hard exercise. Summary HR alone cannot reconstruct the first recovery minute reliably.",
            "Keep recording HR during hard sessions. Suitable stream-equipped efforts will move this card from DATA NEEDED to LEARNING automatically.",
            group="autonomic", evidence="Cole et al. 1999 · Daanen et al. 2012"
        ))

    # Existing V40 chronotropic response: personal observed response rather than age-only diagnosis.
    if hard_max_hr:
        observed_max = max(hard_max_hr)
        median_max = statistics.median(hard_max_hr)
        rhr = metrics.get("latest_rhr")
        cards.append(_v40_card(
            "chronotropic_response", "⏱️", "CHRONOTROPIC RESPONSE", "LEARNING", "purple",
            f"{observed_max:.0f} bpm observed max",
            f"{len(hard_max_hr)} hard effort{'s' if len(hard_max_hr) != 1 else ''} · median peak {median_max:.0f} bpm" + (f" · RHR {rhr} bpm" if isinstance(rhr, (int, float)) else ""),
            "Tracks how heart rate rises with demanding exercise relative to your own observed response and resting state. THE LAB deliberately avoids diagnosing chronotropic incompetence from routine rides or from a crude 220−age ceiling.",
            "More genuine maximal/near-maximal efforts will establish your observed ceiling and response range before any stable longitudinal call is made.",
            group="autonomic", evidence="Chronotropic-response literature · protocol dependent"
        ))
    else:
        cards.append(_v40_card(
            "chronotropic_response", "⏱️", "CHRONOTROPIC RESPONSE", "DATA NEEDED", "grey",
            "—", "No usable peak-HR observations from recent hard efforts.",
            "Chronotropic response describes how appropriately heart rate rises with exercise demand. It requires genuine hard efforts and a trustworthy resting reference.",
            "Future hard/race files with max HR will let THE LAB learn your observed response before attempting any derived index.",
            group="autonomic", evidence="Chronotropic-response literature · protocol dependent"
        ))

    # User-proposed metric: resting Rate-Pressure Product when same-day BP exists.
    rpp = []
    for row in season_wellness:
        hr, sbp = row.get("restingHR"), row.get("systolic")
        if not isinstance(hr, (int, float)) or not isinstance(sbp, (int, float)) or isinstance(hr, bool) or isinstance(sbp, bool):
            continue
        hr, sbp = float(hr), float(sbp)
        if not (25 <= hr <= 120 and 70 <= sbp <= 220):
            continue
        day = _v41_parse_day(row.get("id"))
        if day:
            rpp.append((day, hr * sbp, hr, sbp))
    rpp.sort(key=lambda x: x[0])
    rpp28 = [x for x in rpp if today - timedelta(days=27) <= x[0] <= today]
    if rpp and (today - rpp[-1][0]).days <= 7:
        day, current_rpp, hr, sbp = rpp[-1]
        prior_vals = [x[1] for x in rpp28[:-1]]
        baseline = statistics.median(prior_vals) if prior_vals else None
        status = "TRACKING" if len(rpp28) >= 3 else "LEARNING"
        secondary = f"RHR {hr:.0f} × SBP {sbp:.0f} mmHg"
        if baseline:
            secondary += f" · 28d personal median {baseline:.0f}"
        cards.append(_v40_card(
            "rpp", "❤️", "RATE-PRESSURE PRODUCT · RPP", status, "cyan" if status == "TRACKING" else "purple",
            f"{current_rpp:.0f} bpm·mmHg", secondary,
            "HR × systolic blood pressure is a simple index related to myocardial work/oxygen demand. Here it is used only as resting wellness context; THE LAB does not turn an exercise RPP number into an ischemia threshold or cardiac diagnosis.",
            "More same-protocol blood-pressure mornings will establish your resting HR×SBP range. Exercise RPP would require synchronized exercise blood pressure, not a resting cuff value.",
            group="autonomic", evidence="Gobel et al. · Circulation 1978"
        ))
    else:
        cards.append(_v40_card(
            "rpp", "❤️", "RATE-PRESSURE PRODUCT · RPP", "UNAVAILABLE", "grey",
            "—", "No recent same-day systolic BP + resting HR pair.",
            "Rate-pressure product needs both heart rate and systolic blood pressure. Missing BP is treated as missing data, not as low cardiac workload.",
            "A connected/manual systolic BP value in Intervals wellness will activate resting RPP automatically.",
            group="autonomic", evidence="Gobel et al. · Circulation 1978"
        ))

    # ------------------------------------------------------------------
    # EXERCISE · HEAT · RESPIRATORY
    # ------------------------------------------------------------------

    # Existing V40 DFA alpha-1.
    if dfa_candidates:
        cards.append(_v40_card(
            "dfa_alpha1", "🧬", "DFA α1 · AUTONOMIC THRESHOLD", "LEARNING", "purple",
            f"{len(dfa_candidates)} Alpha1 ride{'s' if len(dfa_candidates) != 1 else ''}",
            "DFA/Alpha1 stream detected in Intervals activity metadata.",
            "DFA α1 analyses fractal beat-to-beat behaviour during exercise and can provide threshold context when collected cleanly. Values around 0.75 and 0.50 are research-supported anchors for VT1/VT2 context, but individual agreement and artifact quality still matter.",
            "Comparable progressive efforts with Alpha1 are required. THE LAB will accumulate usable files before estimating a personal threshold rather than treating one crossing as definitive.",
            group="exercise", evidence="Rogers et al. · 2021–2022"
        ))
    else:
        cards.append(_v40_card(
            "dfa_alpha1", "🧬", "DFA α1 · AUTONOMIC THRESHOLD", "DATA NEEDED", "grey",
            "—", "No DFA/Alpha1 stream detected in recent activity metadata.",
            "DFA α1 needs beat-to-beat-derived Alpha1 data; standard average HR cannot substitute for it. THE LAB therefore refuses to invent an aerobic/anaerobic threshold from missing data.",
            "If a compatible device/app writes Alpha1 into FIT and Intervals exposes dfa_a1, this card will automatically switch to LEARNING.",
            group="exercise", evidence="Rogers et al. · 2021–2022"
        ))

    # User-proposed PSI. Presence of true core temp is required; skin/ambient temp is not substituted.
    if psi_candidates:
        cards.append(_v40_card(
            "psi", "🌡️", "PHYSIOLOGICAL STRAIN INDEX · PSI", "LEARNING", "purple",
            f"{len(psi_candidates)} compatible HEAT file{'s' if len(psi_candidates) != 1 else ''}",
            "True core_temperature + HR streams detected.",
            "The classic Moran PSI combines simultaneous core temperature and heart rate on a 0–10 heat-strain scale. It was developed with core temperature, so THE LAB will not replace that signal with skin or ambient temperature and will not present PSI as a heat-stroke prediction.",
            "THE LAB now knows the required streams exist. A validated stream-level calculation and repeated comparable HEAT sessions are the next step before a personal PSI range is promoted to TRACKING.",
            group="exercise", evidence="Moran et al. · Am J Physiol 1998"
        ))
    elif skin_only_heat:
        cards.append(_v40_card(
            "psi", "🌡️", "PHYSIOLOGICAL STRAIN INDEX · PSI", "DATA NEEDED", "grey",
            "Core temperature required", f"{len(skin_only_heat)} HEAT file{'s' if len(skin_only_heat) != 1 else ''} contain skin/ambient temperature only",
            "PSI requires true core temperature plus heart rate. Skin temperature, Garmin Tempe or ambient temperature describe a different signal and are not silently substituted into the Moran equation.",
            "A CORE-compatible core_temperature stream recorded with HR will move this metric into LEARNING.",
            group="exercise", evidence="Moran et al. · Am J Physiol 1998"
        ))
    else:
        cards.append(_v40_card(
            "psi", "🌡️", "PHYSIOLOGICAL STRAIN INDEX · PSI", "UNAVAILABLE", "grey",
            "—", "No true core-temperature stream detected in recent HEAT activities.",
            "PSI quantifies combined thermal and cardiovascular strain, but the core-temperature term is essential. No core signal means no PSI inference.",
            "If a future HEAT file contains core_temperature + HR, THE LAB will recognize it automatically and begin learning.",
            group="exercise", evidence="Moran et al. · Am J Physiol 1998"
        ))

    # User-proposed aerobic decoupling, surfaced from the existing deterministic Z2 engine.
    aero = build_aerobic_efficiency(season_activities, now=now)
    recent_dec = aero.get("recent_decoupling") if isinstance(aero, dict) else None
    old_dec = aero.get("baseline_decoupling") if isinstance(aero, dict) else None
    dec_change = aero.get("decoupling_change") if isinstance(aero, dict) else None
    if recent_dec is not None:
        if aero.get("status") == "DURABILITY WATCH":
            dec_status, dec_cls = "WATCH", "orange"
        elif aero.get("confidence") in ("HIGH", "MODERATE"):
            dec_status, dec_cls = "TRACKING", "cyan"
        else:
            dec_status, dec_cls = "LEARNING", "purple"
        secondary = f"{aero.get('recent_samples', 0)} recent comparable non-HEAT Z2"
        if old_dec is not None:
            secondary += f" · prior {old_dec:.1f}%"
        if dec_change is not None:
            secondary += f" · {dec_change:+.1f} pp"
        cards.append(_v40_card(
            "aerobic_decoupling", "🔁", "AEROBIC DECOUPLING · ΔEf", dec_status, dec_cls,
            f"{recent_dec:.1f}% recent drift", secondary,
            "Compares power-to-heart-rate behaviour across the first and second halves of steady aerobic work. More drift can reflect heat, hydration, duration, pacing, fatigue or aerobic durability, so THE LAB does not claim that >5% proves one specific cause.",
            "Only comparable steady non-HEAT Z2 sessions build the personal baseline; repeated sessions let THE LAB separate normal durability from a meaningful change.",
            group="exercise", evidence="Coyle & González-Alonso · 2001"
        ))
    else:
        cards.append(_v40_card(
            "aerobic_decoupling", "🔁", "AEROBIC DECOUPLING · ΔEf", "LEARNING", "purple",
            "—", f"{aero.get('recent_samples', 0) if isinstance(aero, dict) else 0} recent comparable Z2 sessions",
            "Aerobic decoupling is most useful when power and HR are observed during repeatable steady endurance sessions. THE LAB deliberately excludes HEAT sessions from the normal baseline.",
            "More ≥40-minute steady Z2 rides with valid power, HR and decoupling will activate the longitudinal drift comparison.",
            group="exercise", evidence="Coyle & González-Alonso · 2001"
        ))

    # Research addition: daily wellness respiratory rate, personalized rather than diagnostic.
    resp_series = _v41_wellness_series(season_wellness, "respiration", 4, 40)
    resp7 = _v41_recent_values(resp_series, today, 7)
    resp_prior = [x for x in resp_series if today - timedelta(days=34) <= x[0] <= today - timedelta(days=7)]
    if resp_series and (today - resp_series[-1][0]).days <= 2:
        current = resp_series[-1][1]
        avg7 = statistics.mean(x[1] for x in resp7) if resp7 else current
        prior = statistics.median(x[1] for x in resp_prior) if resp_prior else None
        status = "TRACKING" if len(resp7) >= 4 and len(resp_prior) >= 7 else "LEARNING"
        secondary = f"7d avg {avg7:.1f} brpm · {len(resp7)} readings"
        if prior:
            secondary += f" · prior median {prior:.1f}"
        cards.append(_v40_card(
            "respiration", "🫁", "WELLNESS RESPIRATORY RATE · fR", status, "cyan" if status == "TRACKING" else "purple",
            f"{current:.1f} brpm", secondary,
            "Respiratory frequency is sensitive to exercise effort and can also provide useful longitudinal wellness context. This card uses the daily Intervals wellness respiration field and treats it as a personal trend—not as a stand-alone respiratory diagnosis.",
            "Repeated readings will establish your normal day-to-day range and let THE LAB cross-check unusual respiratory behaviour against sleep, illness/restrictions, heat and perceived recovery.",
            group="exercise", evidence="Nicolò et al. · 2016–2017"
        ))
    else:
        cards.append(_v40_card(
            "respiration", "🫁", "WELLNESS RESPIRATORY RATE · fR", "UNAVAILABLE", "grey",
            "—", "Intervals wellness is not currently supplying a recent respiration value.",
            "Respiratory frequency can add information about effort and physiological state, but absent data cannot be interpreted as normal breathing.",
            "If your wearable begins syncing the Intervals respiration field, THE LAB will first learn your personal baseline before calling changes.",
            group="exercise", evidence="Nicolò et al. · 2016–2017"
        ))

    # Existing V40 ODI: aggregate SpO2 is not a nocturnal desaturation trace.
    spo2_entries = _v41_wellness_series(season_wellness, "spO2", 50, 100)
    latest_spo2_entry = spo2_entries[-1] if spo2_entries else None
    spo2_recent = bool(latest_spo2_entry and (today - latest_spo2_entry[0]).days <= 2)
    if not spo2_recent:
        secondary = "No recent nocturnal Pulse Ox data"
        if latest_spo2_entry:
            secondary += f" · last aggregate {latest_spo2_entry[0].isoformat()}"
        cards.append(_v40_card(
            "odi", "🌙", "NOCTURNAL DESATURATION · ODI", "UNAVAILABLE", "grey",
            "—", secondary,
            "ODI counts repeated overnight oxygen-desaturation events per hour. A missing or disabled Pulse Ox signal is not a normal result; THE LAB marks the metric unavailable and makes no sleep-apnoea screening inference.",
            "If nocturnal Pulse Ox is re-enabled and a usable time-resolved night trace becomes available, THE LAB can begin evaluating desaturation patterns.",
            group="exercise", evidence="ODI screening literature · time-resolved oximetry required"
        ))
    else:
        cards.append(_v40_card(
            "odi", "🌙", "NOCTURNAL DESATURATION · ODI", "DATA NEEDED", "grey",
            "Night stream required", f"Daily SpO₂ aggregate available · {latest_spo2_entry[1]:.1f}%",
            "A daily SpO₂ value is not an Oxygen Desaturation Index. ODI requires a time-resolved overnight trace so 3–4% drops can be counted relative to the local baseline.",
            "THE LAB sees a current aggregate but will stay silent on ODI until a genuine nocturnal stream is available.",
            group="exercise", evidence="ODI systematic-review literature · 2020"
        ))

    # ------------------------------------------------------------------
    # CAPACITY & TRAINING LOAD
    # ------------------------------------------------------------------

    # Existing V40 functional capacity.
    vo2_value = None
    vo2_delta = None
    vo2_source = None
    if isinstance(vo2_trend.get("wearable_current"), (int, float)):
        vo2_value = float(vo2_trend.get("wearable_current"))
        vo2_delta = vo2_trend.get("wearable_delta28")
        vo2_source = "wearable / Intervals wellness estimate"
    elif isinstance(vo2_trend.get("performance_current"), (int, float)):
        vo2_value = float(vo2_trend.get("performance_current"))
        vo2_delta = vo2_trend.get("performance_delta28")
        vo2_source = "Intervals 5-min-power estimate"
    if vo2_value is not None:
        mets = vo2_value / 3.5
        delta_mets = float(vo2_delta) / 3.5 if isinstance(vo2_delta, (int, float)) else None
        secondary = f"VO₂max {vo2_value:.1f} ml/kg/min · {vo2_source}"
        if delta_mets is not None:
            secondary += f" · {delta_mets:+.1f} MET / 28d"
        cards.append(_v40_card(
            "functional_capacity", "🫁", "FUNCTIONAL CAPACITY · METs", "TRACKING", "cyan",
            f"{mets:.1f} MET", secondary,
            "Converts the current VO₂max estimate into metabolic equivalents (1 MET = 3.5 ml/kg/min). It is useful for longitudinal cardiorespiratory-capacity tracking, not as a daily readiness score or an individual mortality prediction.",
            "THE LAB will follow your own 28/90-day direction and agreement between wearable and performance estimates rather than judging one isolated number.",
            group="capacity", evidence="CRF meta-analyses · population-level evidence"
        ))
    else:
        cards.append(_v40_card(
            "functional_capacity", "🫁", "FUNCTIONAL CAPACITY · METs", "DATA NEEDED", "grey",
            "—", "No usable VO₂max estimate in this Snapshot.",
            "METs are a simple expression of aerobic functional capacity, but THE LAB will not manufacture them without a defensible VO₂max estimate.",
            "A wearable or Intervals performance VO₂max estimate will activate this metric automatically.",
            group="capacity", evidence="CRF meta-analyses · population-level evidence"
        ))

    # Existing V40 load context: useful context, not injury probability.
    atl_ctl = training_state.get("atl_ctl")
    load_ratio = training_state.get("load_ratio")
    if isinstance(atl_ctl, (int, float)) or isinstance(load_ratio, (int, float)):
        elevated = (isinstance(atl_ctl, (int, float)) and atl_ctl >= 1.18) or (isinstance(load_ratio, (int, float)) and load_ratio >= 1.35)
        bits = []
        if isinstance(atl_ctl, (int, float)):
            bits.append(f"ATL/CTL {atl_ctl:.2f}")
        if isinstance(load_ratio, (int, float)):
            bits.append(f"7d / prior 3w ×{load_ratio:.2f}")
        cards.append(_v40_card(
            "load_context", "📈", "LOAD SPIKE CONTEXT", "ELEVATED" if elevated else "CONTROLLED", "orange" if elevated else "green",
            bits[0] if bits else "—", " · ".join(bits[1:]) if len(bits) > 1 else "Current load relationship",
            "Compares acute load with the athlete's established workload. THE LAB uses it as one part of a multifactorial context alongside recovery, calendar and restrictions; it is not a stand-alone injury-risk probability.",
            "Your stable personal range and repeated response matter more than a universal danger cut-off.",
            group="capacity", evidence="Workload literature · ratio interpretation remains debated"
        ))
    else:
        cards.append(_v40_card(
            "load_context", "📈", "LOAD SPIKE CONTEXT", "LEARNING", "grey", "—", "Insufficient load history",
            "Acute-versus-chronic load is useful only when enough history exists to define what 'normal load' actually means for this athlete.",
            "THE LAB will activate this automatically as CTL/ATL and weekly history accumulate.",
            group="capacity", evidence="Workload literature · multifactorial use only"
        ))

    # Research addition: Foster training monotony and strain, personalized rather than diagnostic.
    current_mon = _v41_load_monotony(season_activities, today)
    prior_mon = [_v41_load_monotony(season_activities, today - timedelta(days=7 * i)) for i in (1, 2, 3)]
    prior_valid = [x for x in prior_mon if x.get("monotony") is not None and x.get("total", 0) > 0]
    if current_mon.get("total", 0) > 0 and current_mon.get("monotony") is not None:
        monotony = current_mon["monotony"]
        strain = current_mon["strain"]
        prior_mono_med = statistics.median(x["monotony"] for x in prior_valid) if prior_valid else None
        prior_strain_med = statistics.median(x["strain"] for x in prior_valid) if prior_valid else None
        status = "TRACKING" if len(prior_valid) >= 2 else "LEARNING"
        secondary = f"7d load {current_mon['total']:.0f} · strain {strain:.0f}"
        if prior_mono_med is not None:
            secondary += f" · prior monotony median {prior_mono_med:.2f}"
        if prior_strain_med is not None:
            secondary += f" · prior strain {prior_strain_med:.0f}"
        cards.append(_v40_card(
            "training_monotony", "🔂", "TRAINING MONOTONY · STRAIN", status, "cyan" if status == "TRACKING" else "purple",
            f"Monotony {monotony:.2f}", secondary,
            "Monotony is mean daily 7-day load divided by its day-to-day standard deviation; strain multiplies weekly load by monotony. It describes how much load is being repeated with little variation, but THE LAB does not convert it into an overtraining or injury diagnosis.",
            "THE LAB will compare each week with your own prior weeks and look for repeated combinations of high load, low variation and worsening recovery rather than a universal danger threshold.",
            group="capacity", evidence="Foster · Med Sci Sports Exerc 1998"
        ))
    elif current_mon.get("total", 0) > 0:
        cards.append(_v40_card(
            "training_monotony", "🔂", "TRAINING MONOTONY · STRAIN", "LEARNING", "purple",
            "Uniform load week", f"7d load {current_mon['total']:.0f} · daily-load SD ≈ 0",
            "The classic monotony ratio becomes unstable when every day carries almost identical load because the denominator approaches zero. THE LAB reports the pattern instead of displaying an artificial infinite score.",
            "More natural day-to-day variation will make the ratio finite and allow comparison with prior weeks.",
            group="capacity", evidence="Foster · Med Sci Sports Exerc 1998"
        ))
    else:
        cards.append(_v40_card(
            "training_monotony", "🔂", "TRAINING MONOTONY · STRAIN", "DATA NEEDED", "grey",
            "—", "No training load accumulated in the current 7-day window.",
            "Training monotony and strain require actual daily training-load variation; a zero-load week has no meaningful monotony ratio.",
            "As daily Intervals training load accumulates, THE LAB will calculate the current week and compare it with previous weeks.",
            group="capacity", evidence="Foster · Med Sci Sports Exerc 1998"
        ))

    # Existing V40 multisignal strain: personal baselines, never a clinical OTS label.
    pb = metrics.get("personal_baselines") or {}
    flags = []
    if (pb.get("hrv") or {}).get("color") == "red":
        flags.append("HRV")
    if (pb.get("rhr") or {}).get("color") == "red":
        flags.append("RHR")
    adaptive = metrics.get("adaptive_sleep") or (pb.get("adaptive_sleep") or {})
    sleep_flag = (adaptive.get("color") == "red")
    if isinstance(adaptive.get("current_delta_min"), (int, float)) and adaptive.get("current_delta_min") <= -45:
        sleep_flag = True
    if metrics.get("sleep_quality") == 4:
        sleep_flag = True
    if sleep_flag:
        flags.append("sleep")
    subjective_flag = False
    latest_feeling = (feeling_trend or {}).get("latest") if isinstance(feeling_trend, dict) else None
    if isinstance(latest_feeling, dict) and isinstance(latest_feeling.get("feeling"), (int, float)) and isinstance((feeling_trend or {}).get("avg28"), (int, float)):
        subjective_flag = float(latest_feeling.get("feeling")) <= float((feeling_trend or {}).get("avg28")) - 1.0
    if subjective_flag:
        flags.append("subjective")
    nflags = len(flags)
    if nflags == 0:
        strain_status, strain_class = "CLEAR", "green"
    elif nflags == 1:
        strain_status, strain_class = "MIXED", "grey"
    else:
        strain_status, strain_class = "WATCH", "orange"
    strain_secondary = "No aligned warning pattern" if not flags else "Aligned: " + " · ".join(flags)
    if planning_context.get("health_override"):
        strain_secondary += " · health restriction remains authoritative"
    cards.append(_v40_card(
        "multisignal_strain", "🧠", "MULTISIGNAL STRAIN", strain_status, strain_class,
        f"{nflags}/4 signals", strain_secondary,
        "Cross-checks HRV, resting HR, sleep and subjective recovery so one abnormal metric cannot create an 'overtraining' diagnosis. Consensus literature does not support a single diagnostic OTS marker, so this remains a context signal.",
        "If the same aligned pattern repeats across several mornings, THE LAB can learn the difference between a transient disturbance and persistent strain.",
        group="capacity", evidence="Meeusen et al. · ECSS/ACSM 2013"
    ))

    # V43 reference layer: dynamic personal comparators are rebuilt every Snapshot from the
    # currently available history. Research anchors are shown as context, never as diagnoses.
    si_current_ref = si_series[-1][1] if si_series and (today - si_series[-1][0]).days <= 7 else None
    poincare_current_ref = poincare[-1][3] if poincare and (today - poincare[-1][0]).days <= 7 else None
    rpp_current_ref = rpp[-1][1] if rpp and (today - rpp[-1][0]).days <= 7 else None
    resp_current_ref = resp_series[-1][1] if resp_series and (today - resp_series[-1][0]).days <= 2 else None

    vo2_points = vo2_trend.get("wearable") if isinstance(vo2_trend.get("wearable_current"), (int, float)) else vo2_trend.get("performance")
    mets_values = []
    for p in vo2_points or []:
        try:
            mets_values.append(float(p.get("value")) / 3.5)
        except (TypeError, ValueError):
            pass
    mets_current_ref = (vo2_value / 3.5) if isinstance(vo2_value, (int, float)) else None

    load_ratio_history = _v43_load_ratio_history(season_activities, today, weeks=8)
    load_ratio_values = [v for d, v in load_ratio_history if d < today]
    monotony_values = [x.get("monotony") for x in prior_valid if isinstance(x.get("monotony"), (int, float))]

    cards = _v43_reference_profile(cards, {
        "today": today,
        "hrv_series": hrv_series,
        "hrv_current": (math.exp(statistics.mean(math.log(x[1]) for x in hrv7)) if len(hrv7) >= 3 else None),
        "si_values": [x[1] for x in si_recent[:-1]], "si_current": si_current_ref,
        "poincare_values": [x[3] for x in poincare_recent[:-1]], "poincare_current": poincare_current_ref,
        "hard_max_hr": hard_max_hr,
        "rpp_values": [x[1] for x in rpp28[:-1]], "rpp_current": rpp_current_ref,
        "aero_baseline_decoupling": old_dec, "aero_decoupling_change": dec_change,
        "resp_values": [x[1] for x in resp_prior], "resp_current": resp_current_ref,
        "mets_values": mets_values[:-1] if len(mets_values) > 1 else mets_values, "mets_current": mets_current_ref,
        "load_ratio_values": load_ratio_values, "load_ratio_current": training_state.get("load_ratio"),
        "monotony_values": monotony_values, "monotony_current": current_mon.get("monotony"),
    })

    groups = _v41_metric_groups(cards)  # retained for backwards compatibility / stored reports
    display_sections, gap_cards = _v43_metric_display(cards)
    attention = sum(len(s.get("cards") or []) for s in display_sections if s.get("key") == "attention")
    active = sum(len(s.get("cards") or []) for s in display_sections if s.get("key") == "active")
    learning = sum(len(s.get("cards") or []) for s in display_sections if s.get("key") == "learning")
    data_needed = sum(1 for c in gap_cards if c.get("status") == "DATA NEEDED")
    unavailable = sum(1 for c in gap_cards if c.get("status") == "UNAVAILABLE")
    return {
        "cards": cards,
        "groups": groups,
        "display_sections": display_sections,
        "gap_cards": gap_cards,
        "summary": f"{len(cards)} METRICS · {attention + active} ACTIVE · {learning} LEARNING · {len(gap_cards)} DATA GAPS",
        "gap_summary": f"{data_needed} DATA NEEDED · {unavailable} UNAVAILABLE",
        "note": "Science-derived training/health context only · not a diagnosis. Personal ranges are rebuilt dynamically from the history available at each Snapshot and take priority over generic research anchors. TRACKING means a live longitudinal metric; LEARNING means THE LAB has usable ingredients but wants more comparable data; DATA NEEDED means the required signal/protocol is missing; UNAVAILABLE means the source is not currently being recorded.",
    }


def advanced_physiology_text(bundle):
    bundle = bundle or {}
    cards = bundle.get("cards") or []
    if not cards:
        return "ADVANCED PHYSIOLOGY / LEARNING LAB: unavailable"
    lines = [
        "ADVANCED PHYSIOLOGY / LEARNING LAB (deterministic Python; science-derived context, not medical diagnosis):",
        "- DATA NEEDED and UNAVAILABLE are explicit absence-of-data states, not reassuring/normal findings.",
        "- Clinical thresholds from patient/lab cohorts are context only; personal baselines and protocol quality outrank generic cut-offs.",
        "- Never convert these cards into disease, mortality, ischemia, injury-risk or overtraining diagnoses.",
    ]
    for c in cards:
        line = "- {label}: {status} | {value} | {secondary}. {explanation}".format(
            label=c.get("label"), status=c.get("status"), value=c.get("value"), secondary=c.get("secondary"), explanation=c.get("explanation")
        )
        ref = c.get("reference") or {}
        personal = ref.get("personal") or {}
        if personal.get("value"):
            line += " Personal reference: " + str(personal.get("value")) + "."
            if personal.get("assessment"):
                line += " Current relation: " + str(personal.get("assessment")) + "."
        if ref.get("research"):
            line += " Research context: " + str(ref.get("research"))
        if c.get("evidence"):
            line += " Evidence basis: " + str(c.get("evidence")) + "."
        lines.append(line)
    return "\n".join(lines)

