def _report_json_default(value):
    """Conservative JSON fallback for the stored report payload."""
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if isinstance(value, set):
        return sorted(value)
    return str(value)


def save_latest_report(data, now=None):
    """Persist exactly ONE complete report payload, atomically replacing the previous one.

    This never calls Intervals.icu or the AI Coach. The payload contains only the
    already-computed dashboard/report data, not raw API responses or secrets.
    """
    init_memory_db()
    now = now or get_rome_now()
    generated_at_local = now.isoformat(timespec="seconds")
    generated_at_utc = now.astimezone(ZoneInfo("UTC")).isoformat(timespec="seconds")
    report_data = dict(data or {})
    report_data.pop("best_watts_debug", None)
    report_data.pop("report_save_warning", None)
    payload_json = json.dumps(report_data, ensure_ascii=False, separators=(",", ":"), default=_report_json_default)
    conn = _db_connect()
    try:
        cur = conn.cursor()
        cur.execute(_db_sql("DELETE FROM latest_report"))
        cur.execute(
            _db_sql("INSERT INTO latest_report (singleton_id, generated_at_utc, generated_at_local, app_version, payload_json) VALUES (?, ?, ?, ?, ?)"),
            ("latest", generated_at_utc, generated_at_local, APP_VERSION, payload_json),
        )
        conn.commit()
    finally:
        conn.close()
    return {
        "generated_at_utc": generated_at_utc,
        "generated_at_local": generated_at_local,
        "app_version": APP_VERSION,
        "payload_bytes": len(payload_json.encode("utf-8")),
    }


def _format_report_timestamp(value):
    try:
        dt = datetime.fromisoformat(str(value))
        return dt.strftime("%d/%m/%Y · %I:%M %p")
    except Exception:
        return str(value or "—")


def load_latest_report(include_payload=True):
    """Read the singleton latest report from local/PostgreSQL storage only."""
    rows = _db_execute(
        "SELECT singleton_id, generated_at_utc, generated_at_local, app_version, payload_json FROM latest_report WHERE singleton_id=? LIMIT 1",
        ("latest",), fetch=True,
    )
    if not rows:
        return None
    row = rows[0]
    meta = {
        "generated_at_utc": row.get("generated_at_utc"),
        "generated_at_local": row.get("generated_at_local"),
        "generated_at_local_display": _format_report_timestamp(row.get("generated_at_local")),
        "app_version": row.get("app_version") or "THE LAB",
    }
    raw = row.get("payload_json") or "{}"
    meta["payload_bytes"] = len(raw.encode("utf-8"))
    meta["payload_human"] = _human_bytes(meta["payload_bytes"])
    if include_payload:
        try:
            meta["data"] = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            meta["data"] = None
    return meta


# V27.1: Last Full Report availability is intentionally NOT a session feature.
# The report lives in PostgreSQL/SQLite and the navigation link is always rendered.
# Logging out clears only the Flask login session; it must never hide or delete the stored report.
def get_latest_report_meta():
    report = load_latest_report(include_payload=False)
    if not report:
        return None
    return {k: report.get(k) for k in ("generated_at_utc", "generated_at_local", "generated_at_local_display", "app_version", "payload_bytes", "payload_human")}


