def delete_daily_logs_before(cutoff_date):
    cutoff = _safe_iso_date(cutoff_date)
    if not cutoff:
        raise ValueError("Choose a valid cutoff date")
    count = _count_rows("daily_logs", "WHERE local_date < ?", (cutoff,))
    if count:
        _db_execute("DELETE FROM daily_logs WHERE local_date < ?", (cutoff,))
    return count, cutoff


def run_daily_log_retention_cleanup(now=None):
    """Best-effort once-per-day retention for raw subjective Daily Logs.

    Retains the cutoff date itself and all newer rows, so records are removed only
    when they are strictly older than DAILY_LOG_RETENTION_DAYS. This deliberately
    leaves the 28-day feeling trend intact with a two-week safety margin.
    """
    global _LAST_DAILY_LOG_CLEANUP_DATE
    current = now or datetime.now(ROME_TZ)
    today = current.date()
    cleanup_key = today.isoformat()
    cutoff = (today - timedelta(days=DAILY_LOG_RETENTION_DAYS)).isoformat()
    if _LAST_DAILY_LOG_CLEANUP_DATE == cleanup_key:
        return {"ran": False, "deleted": 0, "cutoff": cutoff}

    deleted, cutoff = delete_daily_logs_before(cutoff)
    _LAST_DAILY_LOG_CLEANUP_DATE = cleanup_key
    return {"ran": True, "deleted": deleted, "cutoff": cutoff}


@app.before_request
def automatic_storage_housekeeping():
    """Run storage housekeeping only inside the authenticated app; public/login views never touch athlete storage."""
    if request.endpoint in {"login", "preview", "pwa_manifest", "pwa_icon_192", "pwa_icon_512", "service_worker"}:
        return
    if not require_login():
        return
    try:
        run_daily_log_retention_cleanup()
    except Exception as exc:
        app.logger.warning("Daily Log auto-cleanup skipped: %s", exc)


def classify_feeling(value):
    value = int(value)
    if value <= 3:
        return "red"
    if value <= 6:
        return "grey"
    return "green"


def compute_feeling_trend(logs=None):
    logs = logs if logs is not None else load_daily_logs(240)
    if not logs:
        return {"latest": None, "avg7": None, "avg28": None, "delta": None, "label": "NO TREND YET", "points": [], "pre_avg": None, "post_avg": None}
    today = get_rome_now().date()
    recent28 = []
    recent7 = []
    pre_vals, post_vals = [], []
    points = []
    for log in logs:
        try:
            d = date.fromisoformat(str(log.get("local_date")))
        except (ValueError, TypeError):
            continue
        age = (today - d).days
        value = log.get("feeling")
        if not isinstance(value, (int, float)):
            continue
        if 0 <= age < 28:
            recent28.append(float(value))
        if 0 <= age < 7:
            recent7.append(float(value))
        phase = str(log.get("phase") or "")
        if phase.startswith("PRE"):
            pre_vals.append(float(value))
        if phase.startswith("POST"):
            post_vals.append(float(value))
        points.append({"date": d.isoformat(), "day": d.strftime("%a"), "time": log.get("local_time"), "value": int(value), "phase": phase})
    avg7 = round(statistics.mean(recent7), 1) if recent7 else None
    avg28 = round(statistics.mean(recent28), 1) if recent28 else None
    delta = round(avg7 - avg28, 1) if avg7 is not None and avg28 is not None else None
    if delta is None:
        label = "BUILDING BASELINE"
    elif delta >= 0.6:
        label = "TRENDING UP"
    elif delta <= -0.6:
        label = "TRENDING DOWN"
    else:
        label = "STABLE"
    return {
        "latest": logs[-1], "avg7": avg7, "avg28": avg28, "delta": delta, "label": label,
        "points": points[-14:],
        "pre_avg": round(statistics.mean(pre_vals[-30:]), 1) if pre_vals else None,
        "post_avg": round(statistics.mean(post_vals[-30:]), 1) if post_vals else None,
    }


