@app.route("/login", methods=["GET", "POST"])
def login():
    error = None
    if request.method == "POST":
        submitted_username = (request.form.get("username") or "").strip()
        submitted_password = request.form.get("password") or ""
        if not APP_USERNAME:
            error = "APP_USERNAME is not configured on the server."
        elif not APP_PASSWORD:
            error = "APP_PASSWORD is not configured on the server."
        else:
            username_ok = hmac.compare_digest(submitted_username.casefold(), APP_USERNAME.casefold())
            password_ok = hmac.compare_digest(submitted_password, APP_PASSWORD)
            if username_ok and password_ok:
                session["logged_in"] = True
                session["username"] = APP_USERNAME
                return redirect(url_for("home"))
            error = "Incorrect username or password."
    return render_template_string(LOGIN_PAGE, error=error, css=BASE_CSS, logo=LOGO_B64, favicon=FAVICON_B64)


