def personal_baseline_text(metrics):
    pb = metrics.get("personal_baselines") or {}
    adaptive = metrics.get("adaptive_sleep") or pb.get("adaptive_sleep") or {}
    def line(label, key):
        item = pb.get(key) or {}
        return f"- {label}: Garmin {item.get('garmin', 'n/a')} | recent {RECENT_BASELINE_DAYS}d {item.get('recent', 'n/a')} | status {item.get('status', 'n/a')}"
    sleep_line = (
        f"- Sleep duration: habitual {adaptive.get('kind', 'n/a')} {adaptive.get('habitual_label', 'n/a')} "
        f"({SLEEP_BASELINE_DAYS}d adaptive; weekday {adaptive.get('weekday_label', 'n/a')} / weekend {adaptive.get('weekend_label', 'n/a')}) "
        f"| current delta {adaptive.get('current_delta_min', 'n/a')} min | Garmin 7h38m retained as reference, not daily penalty target"
    )
    return "\n".join([
        f"PERSONAL BASELINES ({BASELINE_SOURCE}; sleep opportunity is adaptive):",
        line("HRV", "hrv"),
        line("Resting HR", "rhr"),
        sleep_line,
        line("Sleep Score", "sleep_score"),
        line("SpO2", "spo2"),
        line("Sleeping HR", "sleeping_hr"),
        f"- Sleeping respiration: Garmin {pb.get('sleeping_respiration', {}).get('garmin', '11 brpm')} | live value not currently imported",
        f"- Awake respiration: Garmin {pb.get('awake_respiration', {}).get('garmin', '13–14 brpm')} | live value not currently imported",
    ])

def extract_snapshot_daily_question(logs=None, now=None):
    """Return the most recent explicit question in today's Daily Log, if any.

    Saving a Daily Log remains a zero-AI action. When the athlete subsequently
    generates a Snapshot (which already performs the normal AI Coach call), an
    explicit question written in today's note should be answered inside that same
    Snapshot rather than requiring a second /coach-chat call.
    """
    logs = logs if logs is not None else load_daily_logs(80)
    today_iso = (now or get_rome_now()).date().isoformat()
    today_logs = [
        log for log in (logs or [])
        if str(log.get("local_date") or "") == today_iso
    ]
    if not today_logs:
        return None
    # logged_at_utc is an ISO timestamp and is the safest ordering key.  Only
    # the latest Daily Note is authoritative: an older question should not be
    # resurrected after the athlete has logged a newer note without it.
    today_logs.sort(key=lambda log: str(log.get("logged_at_utc") or ""), reverse=True)
    note = str(today_logs[0].get("note") or "").strip()
    if not note or "?" not in note:
        return None
    return note[:1200]


def ask_claude(data_text, metrics, coach_clock, week_memory, planning_context=None, feeling_trend=None, metabolic_context=None, snapshot_question=None, science_context=None):
    planning_context = planning_context or build_planning_context()
    feeling_trend = feeling_trend or compute_feeling_trend()
    metabolic_context = metabolic_context or {}
    slot_lines = "\n".join(
        f'{i+1}. {slot["label"]} | date {slot["date"]} | restriction {slot.get("restriction", "NONE")}'
        + (f' | planned environment {slot.get("training_environment")} | expected demand {slot.get("training_demand") or "COACH"} | athlete note {slot.get("event_note") or "none"}' if slot.get("is_planned_training") else '')
        for i, slot in enumerate(coach_clock.get("next_slots") or [])
    )
    prompt = (
        "You are an expert cycling coach inside THE LAB. The athlete may train twice per day, but V12 structured health, availability, restriction and event data outranks the theoretical schedule. "
        "The COACH CLOCK and HEALTH / AVAILABILITY / EVENT CONTEXT below are authoritative. Activities already logged are completed. Slots removed by Python do not exist for you. "
        "A NO_INTENSITY slot permits only easy aerobic/recovery work. A RACE slot is the event itself and must not receive an extra workout. A PLANNED slot is an athlete-created commitment: its INDOOR/OUTDOOR environment is authoritative. EASY is an intensity ceiling; HARD is expected demand unless health/restrictions or race-proximity safety justify backing off; COACH means choose from context.\n\n"
        "{planning_context}\n\n"
        "{clock_context}\n\n"
        "{week_context}\n\n"
        "{subjective_context}\n\n"
        "{baseline_context}\n\n"
        "{metabolic_context}\n\n"
        "{science_context}\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "Current metrics: Fitness (CTL) {ctl} [{fitness_zone}], Fatigue (ATL) {atl} [{fatigue_zone}], Form (TSB) {tsb} [{form_zone}]. "
        "Health/restriction state is more important than those training-load metrics. If illness or injury explains reduced training, NEVER call the resulting freshness tapering, peaking, race readiness, or improved form. "
        "Instead prioritize health metrics, athlete-reported status and the active restriction. For HRV, resting HR, Sleep Score and SpO2 use personal Garmin baselines plus recent trend, not population thresholds. "
        "SLEEP RULE: sleep duration is interpreted primarily against THE LAB's adaptive 42-day weekday/weekend habitual sleep opportunity. The fixed Garmin 7h38m value is a visible reference, NOT the daily penalty target. Q1/Q2 sleep quality remains a high-priority recovery signal and can partially offset a modest shortfall versus habitual opportunity; severe or accumulating short sleep still matters.\n\n"
        "DETERMINISTIC ENGINE RULE: TRAINING STATE, PHYSIOLOGICAL STATE, AEROBIC EFFICIENCY/DURABILITY and POWER MODEL entries in DATA are computed by Python. Use them as structured context and explain them when relevant; do not silently relabel a health-driven load drop as tapering, and do not treat CP/W′ field estimates as laboratory measurements.\n\n"        "KNOWLEDGE-LAYER RULE: The Cyclist's Science excerpts are athlete-authored explanatory reference material. They rank below Python hard rules, real athlete data, restrictions, planning and personal fueling logic. Generic book fueling advice must NEVER replace the deterministic Nutrition Engine. Cite only excerpts that materially influence the recommendation or a session rationale.\n\n"
        "EVENT RULE: an upcoming registered race changes the purpose and spacing of sessions as race day approaches. Respect days-to-race and do not schedule gratuitous fatigue close to the event. ATHLETE-PLANNED TRAINING RULE: use active Calendar TRAINING entries to shape the days around them and never silently switch their structured environment. "
        "RESTRICTION RULE: temporary restrictions have exact dates. A 12-day no-intensity block means no intentional intensity on any one of those dates, even when CTL/ATL/TSB would otherwise encourage it.\n\n"
        "WEEK-MEMORY RULE: avoid automatically repeating Threshold/TTE, VO2max, Over-Under or sprint/neuromuscular work within about 72h unless there is a clear coaching reason. "
        "HEAT-RESPONSE RULE: activities whose name contains HEAT are deliberate high thermal-strain sessions. Use PREVIOUS TRAINING BLOCKS to inspect their actual interval power, HR response, zones and decoupling instead of judging them from average watts alone. Use the Python PERSONAL HEAT RESPONSE association to contextualize next-morning HRV, but never claim causation and never dismiss low HRV when resting HR, sleep, subjective status or performance also worsen. "
        "SNAPSHOT QUESTION RULE: if SNAPSHOT ATHLETE QUESTION below is not NONE, answer that question explicitly inside the recommendation field during THIS SAME Snapshot AI call. Do not require the athlete to send it again in AI Coach Chat. Put the direct answer first, then continue with the normal coaching recommendation. If it is NONE, behave exactly as usual. "
        "Do not repeat dashboard numbers or baseline ranges unnecessarily; interpret what matters.\n\n"
        "Writing style: concise, visual and decisive. training_load, season_distribution and fatigue_signals normally 1-2 useful sentences; season_outlook 2-3; recommendation 3-5 when needed. "
        "For each session give a specific prescription and short rationale.\n\n"
        "Return ONLY valid JSON with exactly these keys:\n"
        '- "training_load": string\n'
        '- "season_distribution": string\n'
        '- "season_outlook": string\n'
        '- "fatigue_signals": string\n'
        '- "recommendation": string\n'
        '- "science_sources": array of zero to 3 exact The Cyclist\'s Science chunk ids supplied above; include an id only if that excerpt materially influenced recommendation or a session rationale.\n'
        '- "next_sessions": array of exactly 3 objects, SAME ORDER as valid slots. Each object contains "title", "duration", "intensity", "main_set", "why". Python owns the slot/date and will enforce restrictions after your response. Each ordinary workout must fit within 60 minutes.\n\n'
        "VALID NEXT SLOTS:\n{slot_lines}\n\n"
        "SNAPSHOT ATHLETE QUESTION (from today's most recent Daily Note; answer in recommendation if present):\n{snapshot_question}\n\n"
        "DATA:\n{data_text}"
    ).format(
        planning_context=planning_context_text(planning_context),
        clock_context=coach_clock_text(coach_clock), week_context=week_memory_text(week_memory),
        subjective_context=subjective_context_text(feeling_trend), baseline_context=personal_baseline_text(metrics),
        metabolic_context=metabolic_context_text(metabolic_context), science_context=science_prompt_context(science_context), athlete_context=ATHLETE_CONTEXT,
        ctl=metrics["ctl"], fitness_zone=metrics["fitness_zone"],
        atl=metrics["atl"], fatigue_zone=metrics["fatigue_zone"], tsb=metrics["tsb"], form_zone=metrics["form_zone"],
        slot_lines=slot_lines, snapshot_question=(snapshot_question or "NONE"), data_text=data_text,
    )
    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json"},
        json={"model": "claude-sonnet-4-6", "max_tokens": 2600, "messages": [{"role": "user", "content": prompt}]}, timeout=60,
    )
    resp.raise_for_status()
    resp_data = resp.json()
    raw_text = "".join(block.get("text", "") for block in resp_data.get("content", [])).strip()
    if raw_text.startswith("```"):
        raw_text = raw_text.strip("`")
        if raw_text.startswith("json"):
            raw_text = raw_text[4:]
    try:
        parsed = json.loads(raw_text)
    except json.JSONDecodeError as exc:
        preview = raw_text[:300].replace("\n", " ")
        raise json.JSONDecodeError(f"{exc.msg} | raw response preview: {preview}", exc.doc, exc.pos)
    parsed["next_sessions"] = normalize_next_sessions(parsed.get("next_sessions"), coach_clock)
    parsed["science_sources"] = normalize_science_sources(parsed.get("science_sources"), science_context)
    return parsed



def _chat_context_section(label, builder, value):
    if not value:
        return None
    try:
        rendered = builder(value)
        if rendered:
            return f"{label}:\n{rendered}"
    except Exception:
        return None
    return None


def build_ai_coach_chat_context(snapshot):
    """Build a compact, high-signal context from the already-saved Snapshot only.

    No Intervals.icu fetch happens here. Deterministic Python outputs are carried
    forward so the conversational layer explains THE LAB instead of reinventing it.
    """
    snapshot = snapshot or {}
    lines = ["CURRENT THE LAB SNAPSHOT (authoritative for this chat):"]
    lines.append(
        "- CTL {ctl} [{fz}] | ATL {atl} [{az}] | TSB {tsb} [{tz}] | Energy Bank {energy}/100 [{el}] | Race Readiness {race}/100 [{rl}]".format(
            ctl=snapshot.get("ctl", "n/a"), fz=snapshot.get("fitness_zone", "n/a"),
            atl=snapshot.get("atl", "n/a"), az=snapshot.get("fatigue_zone", "n/a"),
            tsb=snapshot.get("tsb", "n/a"), tz=snapshot.get("form_zone", "n/a"),
            energy=snapshot.get("energy_score", "n/a"), el=snapshot.get("energy_label", "n/a"),
            race=snapshot.get("race_readiness_score", "n/a"), rl=snapshot.get("race_readiness_label", "n/a"),
        )
    )
    lines.append(
        "- Latest HRV {hrv} | Resting HR {rhr} | Avg sleep {sleep} | Sleep quality {sq} | Weight {weight}".format(
            hrv=snapshot.get("latest_hrv", "n/a"), rhr=snapshot.get("latest_rhr", "n/a"),
            sleep=snapshot.get("avg_sleep", "n/a"), sq=snapshot.get("sleep_quality", "n/a"),
            weight=snapshot.get("latest_weight", "n/a"),
        )
    )
    if snapshot.get("recommendation"):
        lines.append(f"- COACH SNAPSHOT: {snapshot.get('recommendation')}")

    sessions = snapshot.get("next_sessions") or []
    fuels = snapshot.get("nutrition_plan") or []
    if sessions:
        lines.append("\nUPCOMING SESSIONS + FUEL:")
        for idx, sess in enumerate(sessions[:3]):
            fuel = fuels[idx] if idx < len(fuels) and isinstance(fuels[idx], dict) else {}
            lines.append(
                "- {slot} | {title} | {duration} | {intensity} | Fuel {fueling} | demand {demand} | recovery {recovery}".format(
                    slot=sess.get("slot", f"Session {idx+1}"), title=sess.get("title", "Session"),
                    duration=sess.get("duration", "n/a"), intensity=sess.get("intensity", "n/a"),
                    fueling=fuel.get("intra_cho") or "n/a",
                    demand=fuel.get("session_demand", "n/a"), recovery=fuel.get("recovery_need", "n/a"),
                )
            )
            if sess.get("main_set"):
                lines.append(f"  Main set: {sess.get('main_set')}")
            if sess.get("why"):
                lines.append(f"  Why: {sess.get('why')}")
            if fuel.get("guidance"):
                lines.append(f"  Nutrition: {fuel.get('guidance')}")
            if fuel.get("replenishment_guidance"):
                lines.append(f"  Replenishment: {fuel.get('replenishment_guidance')}")

    sections = [
        _chat_context_section("COACH CLOCK", coach_clock_text, snapshot.get("coach_clock")),
        _chat_context_section("TRAINING STATE", training_state_text, snapshot.get("training_state")),
        _chat_context_section("PHYSIOLOGICAL STATE", physiological_state_text, snapshot.get("physiological_state")),
        _chat_context_section("ADAPTIVE SLEEP", adaptive_sleep_text, snapshot.get("adaptive_sleep")),
        _chat_context_section("AEROBIC EFFICIENCY / DURABILITY", aerobic_efficiency_text, snapshot.get("aerobic_efficiency")),
        _chat_context_section("POWER MODEL", power_model_text, snapshot.get("power_model")),
        _chat_context_section("CURRENT WEEK", week_memory_text, snapshot.get("week_memory")),
        _chat_context_section("PREVIOUS TRAINING BLOCKS", previous_training_blocks_text, snapshot.get("previous_training_blocks")),
        _chat_context_section("PERSONAL HEAT RESPONSE", heat_response_pattern_text, snapshot.get("heat_pattern")),
        _chat_context_section("CALENDAR / RESTRICTIONS", planning_context_text, snapshot.get("planning_context")),
        _chat_context_section("METABOLIC / NUTRITION CONTEXT", metabolic_context_text, snapshot.get("metabolic_context")),
        _chat_context_section("ADVANCED PHYSIOLOGY / LEARNING LAB", advanced_physiology_text, snapshot.get("advanced_physiology")),
    ]
    lines.extend("\n" + x for x in sections if x)
    if snapshot.get("feeling_trend"):
        try:
            lines.append("\nSUBJECTIVE TREND:\n" + subjective_context_text(snapshot.get("feeling_trend"), logs=[]))
        except Exception:
            pass

    vo2 = snapshot.get("vo2_trend") or {}
    if isinstance(vo2, dict) and vo2:
        lines.append(
            "\nVO2MAX TREND (estimated, not measured): wearable {w}, performance {p}, agreement {a}.".format(
                w=vo2.get("wearable_current", "n/a"), p=vo2.get("performance_current", "n/a"), a=vo2.get("agreement", "n/a")
            )
        )
    return "\n".join(lines)


def _normalize_chat_history(raw_history, max_messages=10):
    clean = []
    if not isinstance(raw_history, list):
        return clean
    for item in raw_history[-max_messages:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        text = str(item.get("text") or "").strip()
        if role not in ("user", "assistant") or not text:
            continue
        clean.append({"role": role, "text": text[:2500]})
    return clean


def ask_ai_coach_chat(question, snapshot, history=None, report_meta=None):
    """One explicit AI call against the stored Snapshot; never refresh Intervals.icu."""
    now = get_rome_now()
    notes = load_notes()
    notes_text = "\n".join(
        "- [{category}] {date}: {text}".format(
            category=n.get("category", "GENERAL"), date=n.get("date", ""), text=n.get("text", "")
        ) for n in notes[-50:]
    ) or "(none)"
    snapshot_text = build_ai_coach_chat_context(snapshot)
    science_chat_hits = search_science_knowledge(question, limit=4, diversify=True)
    science_chat_text = science_prompt_context(science_chat_hits)
    history = _normalize_chat_history(history)
    history_text = "\n".join(
        ("ATHLETE" if m["role"] == "user" else "AI COACH") + ": " + m["text"] for m in history
    ) or "(new conversation)"
    report_stamp = (report_meta or {}).get("generated_at_local_display") or "unknown timestamp"

    prompt = (
        "You are AI Coach inside THE LAB, a personal cycling decision dashboard. "
        "Answer the athlete's question using the stored Snapshot below. This is a conversational explanation layer: "
        "do not pretend to refresh Intervals.icu, Garmin, weather, or any external source. The Snapshot was generated at {report_stamp}.\n\n"
        "RULES:\n"
        "- Reply in the same language as the athlete's latest question.\n"
        "- Reason from the Snapshot, recent training blocks, calendar/restrictions, personal patterns and deterministic Nutrition Engine outputs.\n"
        "- Treat Python-derived classifications and guardrails as authoritative. Explain them; do not silently override them.\n"
        "- The Cyclist's Science is an athlete-authored knowledge layer below Python rules, real data, restrictions, planning and personal fueling logic. Generic fueling passages never override the deterministic Nutrition Engine.\n"
        "- The Cyclist's Science works as silent background knowledge. Do not surface book/source citations unless the athlete explicitly asks where a concept came from.\n"
        "- If the data does not support a claim, say what is missing instead of inventing it.\n"
        "- HEAT/HRV findings are associations, not proof of causation.\n"
        "- You may discuss alternatives, but do not claim that the stored Snapshot or calendar has been modified.\n"
        "- Do not mention the underlying AI provider.\n"
        "- Be concise but substantive: normally 2-6 short paragraphs, with a short list only if it materially improves clarity.\n\n"
        "ATHLETE CONTEXT:\n{athlete_context}\n\n"
        "DURABLE MEMORY:\n{notes_text}\n\n"
        "{snapshot_text}\n\n"
        "{science_chat_text}\n\n"
        "CONVERSATION SO FAR:\n{history_text}\n\n"
        "LATEST ATHLETE QUESTION:\n{question}\n"
    ).format(
        report_stamp=report_stamp, athlete_context=ATHLETE_CONTEXT, notes_text=notes_text,
        snapshot_text=snapshot_text, science_chat_text=science_chat_text, history_text=history_text, question=question,
    )

    resp = requests.post(
        "https://api.anthropic.com/v1/messages",
        headers={
            "x-api-key": ANTHROPIC_API_KEY,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        },
        json={
            "model": "claude-sonnet-4-6",
            "max_tokens": 900,
            "messages": [{"role": "user", "content": prompt}],
        },
        timeout=60,
    )
    resp.raise_for_status()
    payload = resp.json()
    answer = "".join(block.get("text", "") for block in payload.get("content", [])).strip()
    if not answer:
        raise ValueError("AI Coach returned an empty answer")
    return answer


def build_vo2max_trend_preview(today=None):
    today = today or date.today()
    wearable = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 68.0},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 68.4},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 68.7},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 69.0},
        {"date": today.isoformat(), "value": 69.2},
    ]
    performance = [
        {"date": (today - timedelta(days=49)).isoformat(), "value": 70.7},
        {"date": (today - timedelta(days=42)).isoformat(), "value": 70.8},
        {"date": (today - timedelta(days=35)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=28)).isoformat(), "value": 71.0},
        {"date": (today - timedelta(days=21)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=14)).isoformat(), "value": 71.4},
        {"date": (today - timedelta(days=7)).isoformat(), "value": 71.8},
        {"date": today.isoformat(), "value": 71.8},
    ]
    # Reuse the chart geometry without making API calls.
    original_w = build_wearable_vo2_series
    original_p = build_performance_vo2_series
    try:
        globals()["build_wearable_vo2_series"] = lambda *_args, **_kwargs: wearable
        globals()["build_performance_vo2_series"] = lambda *_args, **_kwargs: performance
        return build_vo2max_trend([])
    finally:
        globals()["build_wearable_vo2_series"] = original_w
        globals()["build_performance_vo2_series"] = original_p


