@app.route("/last-report")
def last_report():
    if not require_login():
        return redirect(url_for("login"))
    report = load_latest_report(include_payload=True)
    if not report or not report.get("data"):
        return redirect(url_for("home", notice="NO STORED REPORT", detail="Generate a Snapshot first"))
    return render_template_string(
        HOME_PAGE, days=DAYS_BACK, season_days=SEASON_DAYS_BACK,
        data=report["data"], error=None, css=BASE_CSS, logo=LOGO_B64, favicon=FAVICON_B64,
        notes=[], chat_answer=None, chat_error=None, feelings=[], latest_feeling=None,
        app_version=report.get("app_version") or APP_VERSION, clock_preview=get_clock_preview(), is_preview=False,
        report_mode=True, report_meta=report, download_mode=False, chat_context_meta=None,
    )


@app.route("/last-report/download")
def last_report_download():
    if not require_login():
        return redirect(url_for("login"))
    report = load_latest_report(include_payload=True)
    if not report or not report.get("data"):
        return redirect(url_for("home", notice="NO STORED REPORT", detail="Generate a Snapshot first"))
    html = render_template_string(
        HOME_PAGE, days=DAYS_BACK, season_days=SEASON_DAYS_BACK,
        data=report["data"], error=None, css=BASE_CSS, logo=LOGO_B64, favicon=FAVICON_B64,
        notes=[], chat_answer=None, chat_error=None, feelings=[], latest_feeling=None,
        app_version=report.get("app_version") or APP_VERSION, clock_preview=get_clock_preview(), is_preview=False,
        report_mode=True, report_meta=report, download_mode=True, chat_context_meta=None,
    )
    stamp = str(report.get("generated_at_local") or get_rome_now().isoformat())[:16].replace("-", "").replace(":", "").replace("T", "_")
    return Response(
        html,
        mimetype="text/html; charset=utf-8",
        headers={
            "Content-Disposition": f'attachment; filename="the_lab_full_report_{stamp}.html"',
            "Cache-Control": "no-store",
        },
    )


