@app.route("/storage/daily-logs.csv")
def storage_export_daily_csv():
    if not require_login():
        return redirect(url_for("login"))
    rows = _db_execute("SELECT * FROM daily_logs ORDER BY local_date ASC, local_time ASC, logged_at_utc ASC", fetch=True)
    buffer = io.StringIO()
    fields = [
        "local_date", "local_time", "feeling", "status", "note", "restriction_type",
        "status_until", "restriction_until", "phase", "session_count", "today_load",
        "am_done", "pm_done", "context_source", "logged_at_utc", "id",
    ]
    writer = csv.DictWriter(buffer, fieldnames=fields, extrasaction="ignore")
    writer.writeheader()
    for row in rows:
        writer.writerow(row)
    stamp = get_rome_now().strftime("%Y%m%d_%H%M")
    return Response(
        buffer.getvalue(),
        mimetype="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="the_lab_daily_logs_{stamp}.csv"', "Cache-Control": "no-store"},
    )


@app.route("/storage/cleanup", methods=["POST"])
def storage_cleanup():
    if not require_login():
        return redirect(url_for("login"))
    action = (request.form.get("action") or "").strip()
    try:
        if action == "purge_archived":
            deleted = purge_archived_records()
            return redirect(url_for("home", notice="CLEANUP COMPLETE", detail=f"Permanently removed {deleted} archived item(s)"))
        if action == "daily_before":
            deleted, cutoff = delete_daily_logs_before(request.form.get("cutoff_date"))
            return redirect(url_for("home", notice="CLEANUP COMPLETE", detail=f"Removed {deleted} Daily Log(s) before {format_ui_date(cutoff)}"))
        raise ValueError("Unknown cleanup action")
    except (ValueError, TypeError) as exc:
        return redirect(url_for("home", notice="CHECK CLEANUP", detail=str(exc)))


